return-response.set-body:
@{
        // context.Api.Path is e.g. "v1/azure-vm"; the last segment names the option.
        var parts = context.Api.Path.Split('/');
        var id = parts[parts.Length - 1];
        return new JObject(
          new JProperty("object", "list"),
          new JProperty("data", new JArray(
            new JObject(
              new JProperty("id", id),
              new JProperty("object", "deployment"),
              new JProperty("model", id),
              new JProperty("status", "succeeded"),
              new JProperty("capabilities", new JObject(
                new JProperty("chatCompletion", "true")
              ))
            )
          ))
        ).ToString();
      }
